const input = $input.first().json;

// n8n Cloud compatible config: $vars is permitted on n8n Cloud (OS env vars are blocked)
const varsObj = (typeof $vars !== 'undefined' && $vars) ? $vars : {};
const expectedSecret = varsObj.AUTOMATION_SECRET ? String(varsObj.AUTOMATION_SECRET) : '';

// Fail-closed webhook authentication gate
const headers = input.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const signature = headers['x-agencydesk-signature'] || headers['X-AgencyDesk-Signature'] || (authHeader ? String(authHeader).replace(/^Bearer\s+/i, '') : '');
if (!expectedSecret || signature !== expectedSecret) {
  throw new Error('Unauthorized inquiry webhook request.');
}

// Support both direct payloads and n8n Webhook v2 nested body
const item = input.body || input;
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const safeLeadId = (item.lead_id && UUID_RE.test(String(item.lead_id))) ? String(item.lead_id) : null;

const cleanEmail = String(item.email || '').toLowerCase().trim();
const emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail);

// Clean & normalize phone number to E.164 standard (+639913780170 or +1555...)
const rawPhone = String(item.whatsapp || item.phone || '');
let cleanPhone = rawPhone.replace(/[^\d+]/g, '');
if (cleanPhone.startsWith('09')) {
  cleanPhone = '+63' + cleanPhone.slice(1);
} else if (cleanPhone && !cleanPhone.startsWith('+')) {
  cleanPhone = '+' + cleanPhone;
}
const validatedPhone = /^\+[1-9]\d{7,14}$/.test(cleanPhone) ? cleanPhone : null;

// Sanitize Instagram handle
let cleanIg = String(item.instagram || '').trim();
if (cleanIg.includes('instagram.com/')) {
  cleanIg = cleanIg.split('instagram.com/')[1].split('/')[0].split('?')[0];
}
if (cleanIg && !cleanIg.startsWith('@')) {
  cleanIg = '@' + cleanIg;
}

// Calculate initial opportunity qualification score (0 - 100)
let leadScore = 20;
const budgetNum = Number(item.budget) || (Number(item.budget_cents) / 100) || 0;
const safeBudget = Number.isFinite(budgetNum) && budgetNum >= 0 ? Math.round(budgetNum) : 0;
if (safeBudget >= 50000) leadScore += 40;
else if (safeBudget >= 25000) leadScore += 25;
else if (safeBudget >= 10000) leadScore += 10;

if (item.whatsapp_opt_in && validatedPhone) leadScore += 15;
if (cleanIg) leadScore += 10;
if (item.brief && String(item.brief).length > 50) leadScore += 15;

const finalScore = Math.round(Math.min(100, Math.max(0, leadScore)));
const receivedAt = new Date().toISOString();
const syncHash = `${cleanEmail}|${safeBudget}|${validatedPhone || ''}|new`;

return [{
  json: {
    email_valid: emailValid,
    lead_id: safeLeadId,
    contact_name: String(item.contact_name || 'Anonymous Lead').trim().slice(0, 100) || 'Anonymous Lead',
    email: cleanEmail,
    phone: validatedPhone,
    whatsapp: validatedPhone,
    whatsapp_opt_in: Boolean(item.whatsapp_opt_in && validatedPhone),
    instagram: cleanIg || null,
    company: String(item.company || 'Unassigned Company').trim().slice(0, 200) || 'Unassigned Company',
    service: String(item.service || 'Web & Mobile Applications').trim().slice(0, 100) || 'Web & Mobile Applications',
    budget: safeBudget,
    timeline: String(item.timeline || 'Immediate (Next 30 days)').trim(),
    brief: String(item.brief || 'No initial brief provided.').trim().slice(0, 4000) || 'No initial brief provided.',
    source: String(item.source || 'website_inquiry').trim().slice(0, 100) || 'website_inquiry',
    submission_id: item.submission_id || $execution.id,
    lead_score: finalScore,
    sync_hash: syncHash,
    received_at: receivedAt
  }
}];

