const varsObj = (typeof $vars !== 'undefined' && $vars) ? $vars : {};
const lead = $('Normalize & Validate Lead Payload').first().json;
const crmResult = $('Upsert Lead in AgencyDesk CRM').first().json;
const currentItem = $input.first().json || {};

const sheetsSynced = currentItem.sheets_synced !== false;
const leadId = crmResult.lead_id || lead.submission_id;
const crmUrl = crmResult.crm_url || (`${(varsObj.AGENCYDESK_APP_URL || 'https://agencydesk-theta.vercel.app').replace(/\/+$/, '')}/crm/leads?lead=${leadId}`);
const targetPhone = varsObj.OWNER_WHATSAPP_NUMBER || '+639913780170';

const messageText = [
  '🚀 *NEW AGENCYDESK LEAD INQUIRY*',
  '━━━━━━━━━━━━━━━━━━━━━',
  `👤 *Contact:* ${lead.contact_name}`,
  `🏢 *Company:* ${lead.company}`,
  `💼 *Service:* ${lead.service}`,
  `💰 *Budget:* $${Number(lead.budget || 0).toLocaleString()}`,
  `🎯 *Score:* ${lead.lead_score}/100`,
  `📱 *WhatsApp:* ${lead.whatsapp || 'Not provided'} (${lead.whatsapp_opt_in ? '✅ Opted-in' : 'Pending opt-in'})`,
  `📸 *Instagram:* ${lead.instagram || 'Not provided'}`,
  '━━━━━━━━━━━━━━━━━━━━━',
  '📝 *Brief:*',
  `"${lead.brief}"`,
  '━━━━━━━━━━━━━━━━━━━━━',
  sheetsSynced ? '📊 *Google Sheet:* Synced to kinggucci195@gmail.com' : '⚠️ *Google Sheet:* Sync warning (check n8n OAuth)',
  `⚡ *Open Lead:* ${crmUrl}`
].join('\n');

return [{
  json: {
    target_phone: targetPhone,
    lead_phone: lead.whatsapp,
    lead_name: lead.contact_name,
    message: messageText,
    lead_id: leadId,
    crm_url: crmUrl,
    lead_score: lead.lead_score,
    opt_in: lead.whatsapp_opt_in,
    sheets_synced: sheetsSynced,
    dispatch_timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;

// n8n Cloud compatible config: $vars is permitted on n8n Cloud (OS env vars are blocked)
const varsObj = (typeof $vars !== 'undefined' && $vars) ? $vars : {};
const expectedSecret = varsObj.AUTOMATION_SECRET ? String(varsObj.AUTOMATION_SECRET) : '';

// Fail-closed webhook authentication gate
const headers = input.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const signature = headers['x-agencydesk-signature'] || headers['X-AgencyDesk-Signature'] || (authHeader ? String(authHeader).replace(/^Bearer\s+/i, '') : '');
if (!expectedSecret || signature !== expectedSecret) {
  throw new Error('Unauthorized Google Sheets sync webhook request.');
}

const item = input.body || input;

// Loop prevention: suppress sync if triggered by agencydesk_crm
if (item['Last Synced By'] === 'agencydesk_crm' || item.last_synced_by === 'agencydesk_crm') {
  return [{ json: { should_sync: false, reason: 'Suppressed: Origin is AgencyDesk CRM' } }];
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const rawLeadId = item['Lead ID'] || item.lead_id;
const safeLeadId = (rawLeadId && UUID_RE.test(String(rawLeadId))) ? String(rawLeadId) : null;

const cleanEmail = String(item['Email'] || item.email || '').toLowerCase().trim();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cleanEmail)) {
  return [{ json: { should_sync: false, reason: 'Suppressed: Missing or invalid email in Sheets row' } }];
}

const rawPhone = String(item['WhatsApp'] || item.whatsapp || item.phone || '');
let cleanPhone = rawPhone.replace(/[^\d+]/g, '');
if (cleanPhone.startsWith('09')) {
  cleanPhone = '+63' + cleanPhone.slice(1);
} else if (cleanPhone && !cleanPhone.startsWith('+')) {
  cleanPhone = '+' + cleanPhone;
}
const validatedPhone = /^\+[1-9]\d{7,14}$/.test(cleanPhone) ? cleanPhone : null;

let cleanIg = String(item['Instagram'] || item.instagram || '').trim();
if (cleanIg.includes('instagram.com/')) {
  cleanIg = cleanIg.split('instagram.com/')[1].split('/')[0].split('?')[0];
}
if (cleanIg && !cleanIg.startsWith('@')) {
  cleanIg = '@' + cleanIg;
}

let rawStatus = String(item['Status'] || item.status || 'new').toLowerCase().trim().replace(/\s+/g, '_');
if (rawStatus === 'new_inquiry') rawStatus = 'new';
// Note: /api/integrations/n8n/leads/upsert preserves existing 'won' server-side; map 'won' safely to 'proposal_sent'
if (rawStatus === 'won') rawStatus = 'proposal_sent';
const allowedStatuses = ['new', 'contacted', 'qualified', 'proposal_sent', 'lost'];
const safeStatus = allowedStatuses.includes(rawStatus) ? rawStatus : 'new';

const rawBudget = Number(item['Budget'] || item.budget || 0);
const safeBudget = Number.isFinite(rawBudget) && rawBudget >= 0 ? Math.round(rawBudget) : 0;
const rawScore = Number(item['Score'] || item.score || 50);
const safeScore = Number.isFinite(rawScore) ? Math.round(Math.min(100, Math.max(0, rawScore))) : 50;

return [{
  json: {
    should_sync: true,
    lead_id: safeLeadId,
    contact_name: String(item['Contact Name'] || item.contact_name || 'Imported Lead').trim().slice(0, 100) || 'Imported Lead',
    email: cleanEmail,
    phone: validatedPhone,
    whatsapp: validatedPhone,
    whatsapp_opt_in: item['WhatsApp Opt-in'] === 'YES' || Boolean(item.whatsapp_opt_in),
    instagram: cleanIg || null,
    company: String(item['Company'] || item.company || 'Unassigned Company').trim().slice(0, 200) || 'Unassigned Company',
    service: String(item['Service'] || item.service || 'Web & Mobile Applications').trim().slice(0, 100) || 'Web & Mobile Applications',
    brief: String(item['Brief'] || item.brief || 'Lead entered via Google Sheets').trim().slice(0, 4000) || 'Lead entered via Google Sheets',
    budget: safeBudget,
    status: safeStatus,
    score: safeScore,
    notes: item['Notes'] || item.notes || undefined,
    sync_hash: `${cleanEmail}|${safeBudget}|${validatedPhone || ''}|${safeStatus}`,
    source: 'google_sheets',
    last_synced_by: 'sheets_user'
  }
}];

